import { test, expect } from '@playwright/test';

const appearanceKey = 'bma-playground.appearance.v1';
const boardKey = 'bma-playground.board.v1';
const focusKey = 'bma-playground.focus.v1';
const title = 'Polish the welcome screen';
const fixture = [
  { id: 'welcome', status: 'todo', owner: 'Maya', effort: 8 },
  { id: 'shortcuts', status: 'todo', owner: 'Erez', effort: 2 },
  { id: 'onboarding', status: 'doing', owner: 'Erez', effort: 2 },
  { id: 'mobile', status: 'doing', owner: 'Maya', effort: 4 },
  { id: 'tokens', status: 'done', owner: 'Maya', effort: 3 },
  { id: 'repo', status: 'done', owner: 'Erez', effort: 3 }
];
const viewButton = (page, name) => page.getByRole('group', { name: 'Launch view', exact: true }).getByRole('button', { name, exact: true });
const teammate = (page, name) => page.getByRole('group', { name: 'Focus by teammate', exact: true }).getByRole('button', { name, exact: true });
const status = page => page.getByRole('combobox', { name: `Status for ${title}`, exact: true });
const owner = page => page.getByRole('combobox', { name: `Owner for ${title}`, exact: true });
const effort = page => page.getByRole('textbox', { name: `Effort for ${title}`, exact: true });
const saveEffort = page => page.getByRole('button', { name: `Save effort for ${title}`, exact: true });
async function switchView(page, name) {
  await viewButton(page, name).click();
  await expect(viewButton(page, name)).toHaveAttribute('aria-pressed', 'true');
  await expect(viewButton(page, name === 'Board' ? 'Workload' : 'Board')).toHaveAttribute('aria-pressed', 'false');
  await expect(page.locator(name === 'Board' ? '#board' : '#workload')).toBeVisible();
  await expect(page.locator(name === 'Board' ? '#workload' : '#board')).toBeHidden();
}
async function light(page, view) {
  await expect(page.locator('html')).toHaveCSS('color-scheme', 'light');
  await expect(page.locator('html')).toHaveCSS('background-color', 'rgb(243, 246, 252)');
  await expect(page.locator('html')).toHaveCSS('color', 'rgb(24, 49, 79)');
  const card = page.locator(view === 'Board' ? '#board [data-task-id="mobile"]' : '#workload [data-workload-task="mobile"]');
  await expect(card).toBeVisible();
  await expect(card).toHaveCSS('background-color', 'rgb(255, 255, 255)');
  await expect(card.locator('h3')).toHaveCSS('color', 'rgb(24, 49, 79)');
}
async function loads(page, maya, erez) {
  await expect(page.locator('[data-workload-owner="Maya"] [data-workload-load]')).toHaveText(`${maya} / 8 points`);
  await expect(page.locator('[data-workload-owner="Erez"] [data-workload-load]')).toHaveText(`${erez} / 8 points`);
}
async function defaults(page) {
  await expect(page.locator('#board [data-task-id]')).toHaveCount(6);
  for (const column of ['todo', 'doing', 'done']) await expect(page.locator(`[data-column="${column}"] [data-task-id]`)).toHaveCount(2);
  await expect(page.locator('#progress-percent')).toHaveText('33%');
  await expect(page.locator('#completion-count')).toHaveText('2 of 6 tasks');
  await expect(page.locator('#filter-status')).toHaveText('6 tasks shown · All teammates');
}
async function seed(page, tasks, focus = 'All') {
  await page.evaluate(({ tasks, focus, boardKey, focusKey }) => {
    localStorage.setItem(boardKey, JSON.stringify(tasks));
    localStorage.setItem(focusKey, focus);
  }, { tasks, focus, boardKey, focusKey });
  await page.reload();
}

test.beforeEach(async ({ page }) => {
  await page.addInitScript(({ appearanceKey, boardKey, focusKey }) => {
    if (!sessionStorage.getItem('acceptance-initialized')) {
      localStorage.setItem(appearanceKey, 'dark');
      localStorage.removeItem(boardKey);
      localStorage.removeItem(focusKey);
      sessionStorage.setItem('acceptance-initialized', 'yes');
    }
  }, { appearanceKey, boardKey, focusKey });
  await page.goto('/');
  await page.getByRole('button', { name: 'Reset demo board', exact: true }).click();
});

test('[AC-1] Removed appearance UI is absent at desktop and narrow widths in both views and tab traversal', async ({ page }) => {
  for (const width of [1440, 390]) {
    await page.setViewportSize({ width, height: 1080 });
    for (const view of ['Board', 'Workload']) {
      await switchView(page, view);
      await expect(page.locator('#appearance-control, #appearance-status, [data-appearance-option]')).toHaveCount(0);
      await expect(page.getByRole('group', { name: 'Appearance', exact: true, includeHidden: true })).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'Light', exact: true, includeHidden: true })).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'Dark', exact: true, includeHidden: true })).toHaveCount(0);
      await expect(page.getByText(/^Appearance:/)).toHaveCount(0);
      await viewButton(page, view).focus();
      for (let i = 0; i < 45; i++) {
        await page.keyboard.press('Tab');
        const active = page.locator(':focus');
        await expect(active).not.toHaveText(/^(Light|Dark)$/);
        await expect(active).not.toHaveAttribute('data-appearance-option', /.+/);
      }
    }
  }
});

test('[AC-2] Absent preference stays light under light and dark OS preferences with light fields and cream warnings', async ({ page }) => {
  await page.evaluate(key => localStorage.removeItem(key), appearanceKey);
  for (const colorScheme of ['light', 'dark']) {
    await page.emulateMedia({ colorScheme });
    await page.reload();
    await light(page, 'Board');
    await expect(page.getByRole('searchbox', { name: 'Search tasks', exact: true })).toHaveCSS('color-scheme', 'light');
    await expect(page.locator('.search-field')).toHaveCSS('background-color', 'rgb(249, 251, 255)');
    await expect(status(page)).toHaveCSS('color-scheme', 'light');
    await switchView(page, 'Workload');
    await light(page, 'Workload');
    await expect(owner(page)).toHaveCSS('background-color', 'rgb(249, 251, 255)');
    await expect(owner(page)).toHaveCSS('color-scheme', 'light');
    await expect(effort(page)).toHaveCSS('background-color', 'rgb(249, 251, 255)');
    await expect(effort(page)).toHaveCSS('color', 'rgb(24, 49, 79)');
    await expect(page.locator('[data-workload-owner="Maya"] .workload-summary')).toHaveCSS('background-color', 'rgb(255, 250, 243)');
    await expect(page.locator('[data-workload-owner="Maya"] [data-overload-warning]')).toHaveText('! Over capacity · 4 points over');
    await owner(page).focus();
    await page.keyboard.press('Tab');
    await expect(effort(page)).toBeFocused();
    await expect(effort(page)).toHaveCSS('outline-style', 'solid');
    await expect(effort(page)).toHaveCSS('outline-width', '3px');
    await expect(effort(page)).toHaveCSS('outline-color', 'rgb(37, 75, 206)');
  }
});

test('[AC-2] Launch view buttons work by keyboard with visible focus and correct visibility', async ({ page }) => {
  await viewButton(page, 'Board').focus();
  await page.keyboard.press('Tab');
  await expect(viewButton(page, 'Workload')).toBeFocused();
  await expect(viewButton(page, 'Workload')).toHaveCSS('outline-style', 'solid');
  await expect(viewButton(page, 'Workload')).toHaveCSS('outline-width', '3px');
  await page.keyboard.press('Enter');
  await expect(viewButton(page, 'Workload')).toHaveAttribute('aria-pressed', 'true');
  await expect(viewButton(page, 'Board')).toHaveAttribute('aria-pressed', 'false');
  await expect(page.locator('#workload')).toBeVisible();
  await expect(page.locator('#board')).toBeHidden();
  await page.keyboard.press('Shift+Tab');
  await expect(viewButton(page, 'Board')).toBeFocused();
  await page.keyboard.press('Space');
  await expect(viewButton(page, 'Board')).toHaveAttribute('aria-pressed', 'true');
  await expect(viewButton(page, 'Workload')).toHaveAttribute('aria-pressed', 'false');
  await expect(page.locator('#board')).toBeVisible();
  await expect(page.locator('#workload')).toBeHidden();
});

test('[AC-2] [AC-3] Saved Dark is inert without changing customized tasks or Maya focus across reload', async ({ page }) => {
  await page.emulateMedia({ colorScheme: 'dark' });
  const customized = fixture.map(task => task.id === 'welcome' ? { ...task, status: 'doing', owner: 'Erez', effort: 5 } : task);
  await seed(page, customized, 'Maya');
  for (let cycle = 0; cycle < 2; cycle++) {
    await expect(viewButton(page, 'Board')).toHaveAttribute('aria-pressed', 'true');
    await expect(teammate(page, 'Maya')).toHaveAttribute('aria-pressed', 'true');
    await expect(page.locator('#filter-status')).toHaveText('2 tasks shown · Maya');
    await light(page, 'Board');
    await switchView(page, 'Workload');
    await light(page, 'Workload');
    await expect(page.locator('#filter-status')).toHaveText('1 active task shown · Maya');
    await teammate(page, 'All').click();
    await expect(owner(page)).toHaveValue('Erez');
    await expect(effort(page)).toHaveValue('5');
    await expect(page.locator('[data-workload-task="welcome"] .card-top')).toContainText('In progress');
    await loads(page, 4, 9);
    await switchView(page, 'Board');
    await expect(page.locator('[data-column="doing"] [data-task-id="welcome"]')).toBeVisible();
    await expect(status(page)).toHaveValue('doing');
    await teammate(page, 'Maya').click();
    await switchView(page, 'Workload');
    await page.reload();
  }
  await expect(viewButton(page, 'Board')).toHaveAttribute('aria-pressed', 'true');
  await expect(teammate(page, 'Maya')).toHaveAttribute('aria-pressed', 'true');
  await light(page, 'Board');
});

test('[AC-4] Default Board and Workload totals and teammate focus survive view switching and reload', async ({ page }) => {
  await defaults(page);
  await switchView(page, 'Workload');
  await expect(page.locator('#workload .workload-context')).toHaveText('Active effort · To do + In progress. Totals include all tasks regardless of filters; Done adds zero.');
  await expect(page.locator('#filter-status')).toHaveText('4 active tasks shown · All teammates');
  await loads(page, 12, 4);
  await teammate(page, 'Maya').click();
  await expect(page.locator('#filter-status')).toHaveText('2 active tasks shown · Maya');
  await expect(page.locator('#workload [data-workload-task]')).toHaveCount(2);
  await loads(page, 12, 4);
  await page.reload();
  await expect(viewButton(page, 'Board')).toHaveAttribute('aria-pressed', 'true');
  await expect(page.locator('#filter-status')).toHaveText('3 tasks shown · Maya');
  await expect(page.locator('#board [data-task-id]')).toHaveCount(3);
});

test('[AC-4] Keyboard status edit moves welcome to Done and persists completion and capacity', async ({ page }) => {
  await status(page).focus();
  await page.keyboard.press('End');
  await page.keyboard.press('Tab');
  await expect(status(page)).toHaveValue('done');
  await expect(page.locator('[data-column="done"] [data-task-id="welcome"]')).toBeVisible();
  await expect(page.locator('#progress-percent')).toHaveText('50%');
  await expect(page.locator('#completion-count')).toHaveText('3 of 6 tasks');
  await expect(page.locator('#announcement')).toHaveAttribute('aria-live', 'polite');
  await expect(page.locator('#announcement')).toHaveText(`${title} moved to Done.`);
  await switchView(page, 'Workload');
  await loads(page, 4, 4);
  await expect(page.locator('[data-workload-task="welcome"]')).toHaveCount(0);
  await expect(page.locator('[data-workload-owner="Maya"] [data-overload-warning]')).toHaveCount(0);
  await page.reload();
  await expect(status(page)).toHaveValue('done');
  await expect(page.locator('#progress-percent')).toHaveText('50%');
  await switchView(page, 'Workload');
  await loads(page, 4, 4);
});

test('[AC-4] Dragging welcome independently to Done updates completion capacity and persistence', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 1080 });
  await page.locator('[data-task-id="welcome"]').dragTo(page.locator('[data-column="done"]'), { targetPosition: { x: 30, y: 45 } });
  await expect(page.locator('[data-column="done"] [data-task-id="welcome"]')).toBeVisible();
  await expect(page.locator('#board [data-task-id]')).toHaveCount(6);
  await expect(page.locator('#progress-percent')).toHaveText('50%');
  await expect(page.locator('#completion-count')).toHaveText('3 of 6 tasks');
  await expect(page.locator('#announcement')).toHaveText(`${title} moved to Done.`);
  await switchView(page, 'Workload');
  await loads(page, 4, 4);
  await page.reload();
  await expect(status(page)).toHaveValue('done');
  await expect(page.locator('#progress-percent')).toHaveText('50%');
});

test('[AC-4] Status select restores focus and keyboard owner and effort edits recalculate and persist', async ({ page }) => {
  await status(page).selectOption('doing');
  await expect(status(page)).toBeFocused();
  await expect(page.locator('[data-column="doing"] [data-task-id="welcome"]')).toBeVisible();
  await switchView(page, 'Workload');
  await owner(page).focus();
  await page.keyboard.press('End');
  await page.keyboard.press('Tab');
  await expect(owner(page)).toHaveValue('Erez');
  await expect(effort(page)).toBeFocused();
  await expect(page.locator('#announcement')).toHaveText(`${title} reassigned to Erez.`);
  await loads(page, 4, 12);
  await page.keyboard.press('ControlOrMeta+A');
  await page.keyboard.type('5');
  await page.keyboard.press('Enter');
  await expect(effort(page)).toHaveValue('5');
  await expect(effort(page)).toBeFocused();
  await expect(page.locator('#announcement')).toHaveText(`Effort for ${title} saved as 5 points.`);
  await loads(page, 4, 9);
  await effort(page).fill('4');
  await page.keyboard.press('Tab');
  await expect(saveEffort(page)).toBeFocused();
  await page.keyboard.press('Space');
  await expect(saveEffort(page)).toBeFocused();
  await expect(page.locator('#announcement')).toHaveText(`Effort for ${title} saved as 4 points.`);
  await loads(page, 4, 8);
  await expect(page.locator('#save-state')).toHaveText('Saved on this device');
  await page.reload();
  await expect(status(page)).toHaveValue('doing');
  await switchView(page, 'Workload');
  await expect(owner(page)).toHaveValue('Erez');
  await expect(effort(page)).toHaveValue('4');
  await loads(page, 4, 8);
});

test('[AC-4] Invalid effort drafts are rejected accessibly without changing saved effort or totals', async ({ page }) => {
  await switchView(page, 'Workload');
  for (const invalid of ['', '0', '9', '1.5', 'abc']) {
    await effort(page).fill(invalid);
    await saveEffort(page).click();
    await expect(effort(page)).toHaveAttribute('aria-invalid', 'true');
    await expect(effort(page)).toHaveAttribute('aria-describedby', 'effort-error-welcome');
    await expect(page.locator('#effort-error-welcome')).toHaveText('Enter a whole number from 1 to 8. Previous saved effort remains 8 points.');
    await expect(page.locator('#announcement')).toHaveText(`Effort for ${title} was not saved. Enter a whole number from 1 to 8.`);
    await expect(saveEffort(page)).toBeFocused();
    await loads(page, 12, 4);
  }
  await page.reload();
  await switchView(page, 'Workload');
  await expect(effort(page)).toHaveValue('8');
  await expect(page.locator('#effort-error-welcome')).toHaveCount(0);
  await effort(page).fill('1');
  await effort(page).press('Enter');
  await expect(effort(page)).not.toHaveAttribute('aria-invalid', 'true');
  await expect(page.locator('#effort-error-welcome')).toHaveCount(0);
  await loads(page, 5, 4);
});

test('[AC-4] Search teammate intersection empty state and Clear filters preserve tasks and focus All', async ({ page }) => {
  const search = page.getByRole('searchbox', { name: 'Search tasks', exact: true });
  await teammate(page, 'Maya').click();
  await search.fill('welcome');
  await expect(page.locator('#filter-status')).toHaveText('1 task shown · Maya');
  await expect(page.locator('#board [data-task-id]')).toHaveCount(1);
  await expect(page.locator('[data-task-id="welcome"] h3')).toHaveText(title);
  await expect(page.locator('#progress-percent')).toHaveText('33%');
  await search.fill('');
  await expect(page.locator('#filter-status')).toHaveText('3 tasks shown · Maya');
  await expect(page.locator('#board [data-task-id]')).toHaveCount(3);
  await search.fill('welcome');
  await teammate(page, 'Erez').click();
  await expect(page.locator('#filter-status')).toHaveText('0 tasks shown · Erez');
  await expect(page.locator('#board [data-task-id]')).toHaveCount(0);
  await expect(page.locator('#filter-empty')).toBeVisible();
  await expect(page.locator('#filter-empty-title')).toHaveText('No matching tasks');
  await page.getByRole('button', { name: 'Clear filters', exact: true }).click();
  await expect(search).toHaveValue('');
  await expect(teammate(page, 'All')).toBeFocused();
  await expect(teammate(page, 'All')).toHaveAttribute('aria-pressed', 'true');
  await defaults(page);
  await page.reload();
  await defaults(page);
});

test('[AC-4] Search shortcuts clear without losing focus filters and workload totals ignore search', async ({ page }) => {
  await teammate(page, 'Maya').click();
  await page.keyboard.press('/');
  const search = page.getByRole('searchbox', { name: 'Search tasks', exact: true });
  await expect(search).toBeFocused();
  await page.keyboard.type('  WELCOME ');
  await expect(page.locator('#board [data-task-id]')).toHaveCount(1);
  await expect(page.locator('#search-result')).toHaveText('1 task matches “WELCOME”');
  await page.keyboard.press('Escape');
  await expect(search).toHaveValue('');
  await expect(search).not.toBeFocused();
  await expect(page.locator('#filter-status')).toHaveText('3 tasks shown · Maya');
  await switchView(page, 'Workload');
  await search.fill('welcome');
  await expect(page.locator('#filter-status')).toHaveText('1 active task shown · Maya');
  await loads(page, 12, 4);
  await teammate(page, 'Erez').click();
  await expect(page.locator('#filter-empty-title')).toHaveText('No matching active tasks');
  await expect(page.locator('#filter-empty')).toBeVisible();
  await loads(page, 12, 4);
  await page.getByRole('button', { name: 'Clear filters', exact: true }).click();
  await expect(teammate(page, 'All')).toBeFocused();
  await expect(search).toHaveValue('');
  await expect(page.locator('#filter-status')).toHaveText('4 active tasks shown · All teammates');
  await loads(page, 12, 4);
});

test('[AC-4] Reset clears saved edits drafts errors search and teammate focus and announces the fixture', async ({ page }) => {
  await status(page).selectOption('done');
  await switchView(page, 'Workload');
  const mobileEffort = page.getByRole('textbox', { name: 'Effort for Give mobile some love', exact: true });
  await mobileEffort.fill('3');
  await mobileEffort.press('Enter');
  await mobileEffort.fill('9');
  await mobileEffort.press('Enter');
  await expect(page.locator('#effort-error-mobile')).toBeVisible();
  await teammate(page, 'Maya').click();
  await page.locator('#search').fill('mobile');
  await page.getByRole('button', { name: 'Reset demo board', exact: true }).click();
  await expect(page.locator('#announcement')).toHaveText('Demo board reset. Two of six tasks complete.');
  await expect(page.locator('#search')).toHaveValue('');
  await expect(teammate(page, 'All')).toHaveAttribute('aria-pressed', 'true');
  await expect(page.locator('.effort-error')).toHaveCount(0);
  await expect(effort(page)).toHaveValue('8');
  await expect(mobileEffort).toHaveValue('4');
  await loads(page, 12, 4);
  await switchView(page, 'Board');
  await defaults(page);
  await expect(status(page)).toHaveValue('todo');
  await page.reload();
  await defaults(page);
  await switchView(page, 'Workload');
  await expect(mobileEffort).toHaveValue('4');
});

test('[AC-4] Corrupt persisted boards and invalid teammate focus fall back to the six-task fixture', async ({ page }) => {
  for (const raw of ['bad json', '{}', 'null', '[]', '[null]', JSON.stringify(Array(6).fill(fixture[0]))]) {
    await page.evaluate(({ raw, boardKey, focusKey }) => {
      localStorage.setItem(boardKey, raw);
      localStorage.setItem(focusKey, 'Unknown teammate');
    }, { raw, boardKey, focusKey });
    await page.reload();
    await defaults(page);
    await expect(status(page)).toHaveValue('todo');
    await switchView(page, 'Workload');
    await loads(page, 12, 4);
    await expect(owner(page)).toHaveValue('Maya');
    await expect(effort(page)).toHaveValue('8');
    await page.reload();
    await defaults(page);
  }
});

test('[AC-4] Storage normalization keeps valid editable fields and restores invalid fields and trusted display copy', async ({ page }) => {
  const saved = fixture.map(task => ({ ...task }));
  saved[0] = { ...saved[0], status: 'doing', owner: 'Erez', effort: 5, title: 'Untrusted title', description: 'Untrusted description', initials: 'XX', color: 'lilac' };
  saved[3] = { ...saved[3], status: 'unknown', owner: 'Unknown', effort: 9 };
  delete saved[1].effort;
  await seed(page, saved);
  for (let cycle = 0; cycle < 2; cycle++) {
    await expect(status(page)).toHaveValue('doing');
    await expect(page.locator('[data-task-id="welcome"] h3')).toHaveText(title);
    await expect(page.getByText('Untrusted title', { exact: true })).toHaveCount(0);
    await expect(page.getByText('Untrusted description', { exact: true })).toHaveCount(0);
    await expect(page.locator('[data-task-id="welcome"] .avatar')).toHaveText('EW');
    await expect(page.locator('[data-status-for="mobile"]')).toHaveValue('doing');
    await switchView(page, 'Workload');
    await expect(owner(page)).toHaveValue('Erez');
    await expect(effort(page)).toHaveValue('5');
    await expect(page.locator('[data-owner-for="mobile"]')).toHaveValue('Maya');
    await expect(page.locator('[data-effort-for="mobile"]')).toHaveValue('4');
    await expect(page.locator('[data-effort-for="shortcuts"]')).toHaveValue('2');
    await loads(page, 4, 9);
    await page.reload();
  }
});

test('[AC-2] [AC-3] [AC-4] Unavailable localStorage retains light usable views and existing unsaved-change fallback', async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, 'localStorage', { configurable: true, get() { throw new DOMException('Storage unavailable', 'SecurityError'); } });
  });
  await page.reload();
  await defaults(page);
  await light(page, 'Board');
  await expect(page.locator('#save-state')).toHaveText('Changes last until you close this page');
  await expect(page.locator('#announcement')).not.toContainText(/appearance/i);
  await status(page).selectOption('doing');
  await expect(status(page)).toHaveValue('doing');
  await expect(page.locator('#announcement')).toHaveText(`${title} moved to In progress.`);
  await switchView(page, 'Workload');
  await light(page, 'Workload');
  await owner(page).selectOption('Erez');
  await effort(page).fill('5');
  await effort(page).press('Enter');
  await loads(page, 4, 9);
  await expect(effort(page)).toHaveValue('5');
  await teammate(page, 'Maya').click();
  await expect(page.locator('#filter-status')).toHaveText('1 active task shown · Maya');
  await page.locator('#search').fill('mobile');
  await expect(page.locator('#workload [data-workload-task="mobile"]')).toBeVisible();
  await expect(page.locator('#announcement')).not.toContainText(/appearance/i);
  await page.reload();
  await defaults(page);
  await light(page, 'Board');
  await switchView(page, 'Workload');
  await light(page, 'Workload');
